func (p *Prober) Probe(ctx context.Context) error {
	regions, err := p.Regions(ctx)
	if err != nil {
		return fmt.Errorf("list OCI regions: %w", err)
	}
	var (
		mu  sync.Mutex
		wg  sync.WaitGroup
		rtt = map[string]time.Duration{}
	)
	slots := make(chan struct{}, rttWorkers)
	for _, region := range regions {
		if !ociRegionName.MatchString(region) {
			continue
		}
		wg.Add(1)
		go func() {
			defer wg.Done()
			slots <- struct{}{}
			defer func() { <-slots }()
			if median, ok := p.median(ctx, region); ok {
				mu.Lock()
				rtt[region] = median
				mu.Unlock()
			}
		}()
	}
	wg.Wait()
	if err := ctx.Err(); err != nil {
		return err
	}
	p.mu.Lock()
	p.last, p.at = rtt, p.Now()
	p.mu.Unlock()
	return nil
}

func (p *Prober) median(ctx context.Context, region string) (time.Duration, bool) {
	address := "objectstorage." + region + ".oraclecloud.com:443"
	var samples []time.Duration
	for range RTTSamples {
		attempt, cancel := context.WithTimeout(ctx, RTTTimeout)
		start := p.Now()
		conn, err := p.Dial(attempt, "tcp", address)
		cancel()
		if err != nil {
			continue
		}
		samples = append(samples, p.Now().Sub(start))
		_ = conn.Close()
	}
	if len(samples) == 0 {
		return 0, false
	}
	slices.Sort(samples)
	return samples[len(samples)/2], true
}

func (p *Prober) Latest() (map[string]time.Duration, time.Time) {
	p.mu.Lock()
	defer p.mu.Unlock()
	return maps.Clone(p.last), p.at
}

chosen.text:
func NewChosenPool(observed *OCIPool, store RecordStore, client *rootoci.Client, current func(context.Context, Record) (rootoci.PoolChildExpectation, error)) (*ChosenPool, error) {
	if observed == nil || store == nil || client == nil || current == nil {
		return nil, errors.New("chosen capacity requires read-only OCI discovery, durable state and authenticated root lifecycle authority")
	}
	return &ChosenPool{observed: observed, store: store, root: client, current: current}, nil
}

func (pool *ChosenPool) PrepareGrowth(ctx context.Context, record Record) (rootoci.PoolChildExpectation, error) {
	if record.Action == nil || record.Action.Kind != Up || !entityid.Valid(record.Action.ID) || record.Recipe == nil || record.Reservation == nil || record.Recipe.Validate() != nil || record.Recipe.Cell != pool.observed.cell ||
		record.Reservation.OperationID != record.Action.ID || record.Reservation.RecipeSHA256 != record.Recipe.SHA256() {
		return rootoci.PoolChildExpectation{}, fmt.Errorf("%w: exact original birth and reservation are not durable", ErrCapacityPending)
	}
	selected, err := pool.selectors(ctx, record)
	if err != nil {
		return rootoci.PoolChildExpectation{}, err
	}
	bundle, err := hostenroll.ParsePublicBundle([]byte(record.Recipe.Metadata[hostboot.EnrollmentMetadataKey]))
	if err != nil {
		return rootoci.PoolChildExpectation{}, err
	}
	if selected.OperationID != "" && selected.OperationID != record.Action.ID || selected.ReservationID != "" && selected.ReservationID != record.Reservation.OperationID || selected.RecipeSHA256 != "" && selected.RecipeSHA256 != record.Recipe.SHA256() ||
		len(selected.PublicCAPEM) != 0 && !bytes.Equal(selected.PublicCAPEM, []byte(bundle.CAPEM)) || len(selected.AvailabilityDomains) != 0 && !slices.Equal(selected.AvailabilityDomains, record.Recipe.AvailabilityDomains) {
		return rootoci.PoolChildExpectation{}, errors.New("current selectors cannot replace the original durable pool birth")
	}
	selected.OperationID, selected.ReservationID, selected.RecipeSHA256 = record.Action.ID, record.Reservation.OperationID, record.Recipe.SHA256()
	selected.PublicCAPEM, selected.AvailabilityDomains = []byte(bundle.CAPEM), slices.Clone(record.Recipe.AvailabilityDomains)
	return selected, nil
}

func (pool *ChosenPool) Grow(ctx context.Context, from int) error {
	record, _, err := pool.store.Load(ctx)
	if err != nil {
		return err
	}
	if from < 0 || from >= MaxPoolNodes || record.From != from || record.TargetFrom == nil || record.Child == nil {
		return fmt.Errorf("%w: exact original root birth is not durable", ErrCapacityPending)
	}
	current, err := pool.PrepareGrowth(ctx, record)
	if err != nil {
		return err
	}
	original := *record.Child
	if original.Cell != current.Cell || original.OperationID != current.OperationID || original.ReservationID != current.ReservationID || original.RecipeSHA256 != current.RecipeSHA256 || !bytes.Equal(original.PublicCAPEM, current.PublicCAPEM) || !slices.Equal(original.AvailabilityDomains, current.AvailabilityDomains) {
		return errors.New("durable root birth differs from its original recipe and reservation")
	}
	original.GrantSHA256, original.Generation, original.Epoch = current.GrantSHA256, current.Generation, current.Epoch
	view, err := pool.root.AdvancePoolChild(ctx, original)
	if err != nil {
		return errors.Join(ErrCapacityPending, err)
	}
	if view.Stage != "attached" || view.Cell != original.Cell || view.OperationID != original.OperationID || view.ReservationID != original.ReservationID || view.RecipeSHA256 != original.RecipeSHA256 || view.InstanceID == "" || !naming.IsNode(view.Node, original.Cell) {
		return errors.New("root advance did not return the exact original attached child")
	}
	return nil
}

func (s *Scaler) Tick(ctx context.Context) error {
	snapshot := s.Leader.Current()
	if !snapshot.CanMutate() {
		s.history = History{}
		s.containerHistory = History{}
		s.mu.Lock()
		s.status, s.addresses = Status{}, nil
		s.mu.Unlock()
		return nil
	}
	record, revision, err := s.Store.Load(ctx)
	if err != nil {
		return fmt.Errorf("load node scaler record: %w", err)
	}
	// Replay retained root operations before discovery or fresh purchase gates.
	var recoveryErr error
	var expired *InFlight
	if record.Action != nil {
		switch {
		case record.Action.Kind == Up && record.Action.Step == stepGrow && record.Child != nil:
			if err := s.Leader.Guard(ctx, snapshot.Epoch); err != nil {
				return err
			}
			recoveryErr = s.Pool.Grow(ctx, record.From)
			if recoveryErr == nil {
				record.Action.Step = stepEnroll
			}
		case record.Retirement != nil && (record.Action.Step == stepRemove || record.Action.Step == stepEnroll):
			if err := s.Leader.Guard(ctx, snapshot.Epoch); err != nil {
				return err
			}
			recoveryErr = s.Pool.Remove(ctx, record.Retirement.InstanceID)
			if recoveryErr == nil {
				if record.Action.Kind == Up {
					expired, record.Action = record.Action, nil
				} else {
					record.Action.Step = stepGone
				}
			}
		}
	}
	pool, err := s.Pool.Observe(ctx)
	if err != nil {
		return fmt.Errorf("observe node pool: %w", err)
	}
	if s.Control == nil {
		return errors.New("SwarmKit control API is unavailable")
	}
	hosts, err := s.Control.ListNodes(ctx, &api.ListNodesRequest{})
	if err != nil {
		return fmt.Errorf("list SwarmKit nodes: %w", err)
	}
	t := &tick{epoch: snapshot.Epoch, now: s.Now(), record: record, pool: pool, hosts: hosts.Nodes}
	if recoveryErr != nil {
		t.pool.Pending = recoveryErr.Error()
	}
	if expired != nil {
		s.queue(t, decisionlog.Decision{Kind: decisionlog.KindHeld, Rule: "nodescale.launch-expired", Subject: s.regionSubject(),
			Summary: fmt.Sprintf("retired original unenrolled child of %s", expired.ID), Reason: fmt.Sprintf("no SwarmKit ready node within %s", LaunchTimeout)})
	}
	t.obs = s.observe(t.pool, hosts.Nodes)
	t.loads = countedLoads(s.Loads(), t.obs)
	s.mu.Lock()
	s.addresses = t.obs.addresses
	s.mu.Unlock()
	s.history.Add(Measure(t.obs.nodes, t.loads, t.now))
	container, _ := containerSample(t)
	s.containerHistory.Add(container)
	if t.record.Action != nil && recoveryErr == nil {
		if err := s.advance(ctx, t); err != nil {
			return err
		}
	}
	if t.record.Action == nil && t.pool.Pending != "" {
		if err := s.Leader.Guard(ctx, t.epoch); err != nil {
			return err
		}
		if err := s.Pool.Recover(ctx); err != nil {
			t.pool.Pending = err.Error()
		}
	}
	allowance, fresh := s.Allowance(t.now)
	if !fresh {
		allowance = t.obs.nodes
	}
	samples := s.history.Samples()
	decision, err := s.decide(ctx, t, State{Nodes: t.obs.nodes, Allowance: allowance, LastChange: t.record.LastChange,
		Busy: t.record.Action != nil, Samples: samples})
	if err != nil {
		return err
	}
	status := s.buildStatus(t, decision, allowance, fresh, samples, s.costOf(ctx, t.pool))
	status.RTTMillis = s.roundTrips()
	t.record.Status = status
	if err := s.Leader.Guard(ctx, t.epoch); err != nil {
		return err
	}
	if _, err := s.Store.Save(ctx, t.record, revision); err != nil {
		return fmt.Errorf("save node scaler record: %w", err)
	}
	s.mu.Lock()
	s.status = status
	s.mu.Unlock()
	for _, entry := range t.journal {
		s.Journal(ctx, entry)
	}
	return nil
}

func (s *Scaler) grow(ctx context.Context, t *tick) error {
	if t.record.Child != nil {
		if err := s.Leader.Guard(ctx, t.epoch); err != nil {
			return err
		}
		if err := s.Pool.Grow(ctx, t.record.From); err != nil {
			t.pool.Pending = err.Error()
			return nil
		}
		t.record.Action.Step = stepEnroll
		return nil
	}
	if t.pool.Pending != "" {
		return nil
	}
	allowance, fresh := s.Allowance(t.now)
	if !fresh || allowance <= t.obs.nodes {
		t.pool.Pending = "a fresh spending allowance for another node is unavailable"
		return nil
	}
	var freshRecipe Recipe
	var err error
	if t.record.Recipe != nil && t.record.Recipe.Capacity.Role == RoleWasm {
		if s.FunctionRecipe == nil {
			t.pool.Pending = "current isolated function host recipe authority is unavailable"
			return nil
		}
		freshRecipe, err = s.FunctionRecipe(ctx, t.record.Recipe.Capacity.Architecture)
	} else {
		freshRecipe, err = s.Recipe(ctx)
	}
	if err != nil {
		if errors.Is(err, ErrCapacityPending) {
			t.pool.Pending = err.Error()
			return nil
		}
		return fmt.Errorf("read node recipe: %w", err)
	}
	if err := freshRecipe.Validate(); err != nil {
		return fmt.Errorf("validate node recipe: %w", err)
	}
	if t.record.Recipe == nil {
		t.record.Recipe = new(freshRecipe)
		return nil
	}
	if freshRecipe.SHA256() != t.record.Recipe.SHA256() {
		t.pool.Pending = "the durable chosen capacity recipe is no longer currently qualified"
		return nil
	}
	recipe := *t.record.Recipe
	if t.record.TargetFrom == nil {
		size, err := s.Pool.TargetSize(ctx, recipe)
		if err != nil {
			return fmt.Errorf("read selected pool starting size: %w", err)
		}
		t.record.TargetFrom = new(size)
		return nil
	}
	if t.record.Reservation == nil {
		if s.Reserve == nil {
			t.pool.Pending = "home capacity reservation authority is unavailable"
			return nil
		}
		receipt, err := s.Reserve(ctx, t.record.Action.ID, recipe)
		if err != nil {
			t.pool.Pending = fmt.Sprintf("home capacity reservation is pending: %v", err)
			return nil
		}
		t.record.Reservation = new(receipt)
		return nil
	}
	child, err := s.Pool.PrepareGrowth(ctx, t.record)
	if err != nil {
		t.pool.Pending = err.Error()
		return nil
	}
	t.record.Child = new(child)
	return nil
}

image.text:
func QualifyImage(ctx context.Context, input ImageQualification, roots trust.Keyring,
	openEvidence func(context.Context, string) (io.ReadCloser, error), now time.Time,
) (image QualifiedImage, expires time.Time, err error) {
	defer func() {
		if err != nil {
			image, expires = QualifiedImage{}, time.Time{}
			err = fmt.Errorf("%w: host image qualification: %w", ErrCapacityPending, err)
		}
	}()
	if input.Expected.OCIImageOCID == "" || input.Expected.Architecture == "" || now.IsZero() || openEvidence == nil {
		return image, expires, errors.New("exact image, native architecture, current time and retained evidence reader are required")
	}
	if err := (Capacity{Role: input.Role, Architecture: input.Expected.Architecture, Shape: PreferredShape}).Validate(); err != nil {
		return image, expires, err
	}
	verified, err := release.VerifyImageCurrent(input.Receipt, input.Delegation, roots, input.Expected, now)
	if err != nil {
		return image, expires, err
	}
	receipt := verified.Receipt()
	expires, err = currentImageProofDeadline(now, input.Receipt, input.Delegation)
	if err != nil {
		return image, expires, err
	}
	candidate := release.ProductionExpectation{SourceRevision: receipt.SourceRevision, ArtifactSHA256: receipt.ImageSHA256,
		QualificationSHA256: receipt.QualificationSHA256, Cell: receipt.OCIRegion, Environment: input.Expected.Environment,
		Runtime: release.ProductionRuntime, Architecture: receipt.Architecture, Role: "orchestrator"}
	proofs := []release.ProductionProof{*receipt.Production}
	if input.Role != RoleManager {
		if input.RoleProduction == nil {
			return image, expires, fmt.Errorf("no independent %s worker qualification for the final disk", input.Role)
		}
		proofs = append(proofs, *input.RoleProduction)
	}
	for index, proof := range proofs {
		if index > 0 {
			candidate.Role = input.Role
		}
		qualification, err := release.VerifyProductionCurrent(proof.Qualification, proof.Delegation, roots, candidate, now)
		if err != nil {
			return image, expires, err
		}
		deadline, err := currentImageProofDeadline(now, proof.Qualification, proof.Delegation)
		if err != nil {
			return image, expires, err
		}
		if deadline.Before(expires) {
			expires = deadline
		}
		for _, evidence := range qualification.Evidence {
			if err := verifyImageEvidence(ctx, openEvidence, evidence); err != nil {
				return image, expires, err
			}
		}
	}
	if err := ctx.Err(); err != nil {
		return image, expires, err
	}
	// The current signed final disk pins the installed runtime; no additional manifest is inferred.
	return QualifiedImage{ID: receipt.OCIImageOCID, Architecture: receipt.Architecture, Role: input.Role,
		RuntimeManifestDigest: receipt.ImageSHA256}, expires, nil
}

func currentImageProofDeadline(now time.Time, wires ...[]byte) (time.Time, error) {
	var expires time.Time
	for _, wire := range wires {
		if len(wire) == 0 {
			continue
		}
		envelope, err := trust.DecodeEnvelope(wire)
		if err != nil {
			return time.Time{}, err
		}
		if envelope.IssuedAt.After(now) || !now.Before(envelope.ExpiresAt) {
			return time.Time{}, errors.New("image or qualification authority is not currently valid")
		}
		if expires.IsZero() || envelope.ExpiresAt.Before(expires) {
			expires = envelope.ExpiresAt
		}
	}
	return expires, nil
}

func verifyImageEvidence(ctx context.Context, open func(context.Context, string) (io.ReadCloser, error), evidence release.ProductionGateEvidence) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	reader, err := open(ctx, evidence.SHA256)
	if err != nil {
		return fmt.Errorf("read retained %s evidence: %w", evidence.Gate, err)
	}
	if reader == nil {
		return fmt.Errorf("retained %s evidence reader is missing", evidence.Gate)
	}
	digest := sha256.New()
	count, readErr := io.Copy(digest, io.LimitReader(reader, evidence.Bytes+1))
	if err := errors.Join(readErr, reader.Close()); err != nil {
		return fmt.Errorf("read retained %s evidence: %w", evidence.Gate, err)
	}
	if count != evidence.Bytes || hex.EncodeToString(digest.Sum(nil)) != evidence.SHA256 {
		return fmt.Errorf("retained %s evidence differs from the signed size or SHA-256", evidence.Gate)
	}
	return nil
}

func VerifyImageCurrent(envelopeWire, delegationWire []byte, roots trust.Keyring,
	expected ImageExpectation, now time.Time,
) (VerifiedImage, error) {
	if err := validateImageExpectation(expected); err != nil {
		return VerifiedImage{}, err
	}
	envelope, delegationEnvelope, err := decodeEnvelopePair(envelopeWire, delegationWire)
	if err != nil {
		return VerifiedImage{}, err
	}
	receipt, err := decodeCanonicalPayload[ImageReceipt](envelope.Payload)
	if err != nil {
		return VerifiedImage{}, err
	}
	if err := receipt.Validate(); err != nil {
		return VerifiedImage{}, err
	}
	if err := matchImageExpectation(receipt, expected); err != nil {
		return VerifiedImage{}, err
	}
	scope := ImageScope(receipt, expected.Environment)
	delegation, err := trust.VerifyDelegationCurrent(delegationEnvelope, roots, now, delegationPolicy())
	if err != nil {
		return VerifiedImage{}, fmt.Errorf("verify current release delegation: %w", err)
	}
	if _, err := trust.VerifyDelegatedCurrent(envelope, scope, delegation, now, receiptPolicy()); err != nil {
		return VerifiedImage{}, fmt.Errorf("verify current signed image receipt: %w", err)
	}
	productionExpiry, err := verifyImageProduction(receipt, expected.Environment, roots, now)
	if err != nil {
		return VerifiedImage{}, err
	}
	proof, err := proofFor(envelope)
	if err != nil {
		return VerifiedImage{}, err
	}
	if productionExpiry.Before(proof.expiresAt) {
		proof.expiresAt = productionExpiry
	}
	return VerifiedImage{receipt: receipt, proof: proof}, nil
}

func verifyImageProduction(receipt ImageReceipt, environment string, roots trust.Keyring, now time.Time) (time.Time, error) {
	if receipt.Production == nil {
		return time.Time{}, fmt.Errorf("%w: signed image contains no independent qualification", ErrProductionQualification)
	}
	expected := ProductionExpectation{SourceRevision: receipt.SourceRevision, ArtifactSHA256: receipt.ImageSHA256,
		QualificationSHA256: receipt.QualificationSHA256, Cell: receipt.OCIRegion, Environment: environment,
		Runtime: ProductionRuntime, Architecture: receipt.Architecture, Role: "orchestrator"}
	if _, err := VerifyProductionCurrent(receipt.Production.Qualification, receipt.Production.Delegation, roots, expected, now); err != nil {
		return time.Time{}, err
	}
	envelope, err := trust.DecodeEnvelope(receipt.Production.Qualification)
	if err != nil {
		return time.Time{}, err
	}
	expires := envelope.ExpiresAt
	if len(receipt.Production.Delegation) > 0 {
		delegation, err := trust.DecodeEnvelope(receipt.Production.Delegation)
		if err != nil {
			return time.Time{}, err
		}
		if delegation.ExpiresAt.Before(expires) {
			expires = delegation.ExpiresAt
		}
	}
	return expires, nil
}

func VerifyProductionCurrent(wire, delegationWire []byte, roots trust.Keyring, expected ProductionExpectation, now time.Time) (ProductionQualification, error) {
	var qualification ProductionQualification
	gates := []string{"runtime-ha", "workload-safety"}
	schema := ProductionQualificationSchema
	if expected.Role == FoundationWriterRole {
		schema = FoundationWriterQualificationSchema
		gates = append(gates, RootCredentialBoundaryGate)
	}
	validRuntime := expected.Runtime == ProductionRuntime
	if expected.Role == FoundationWriterRole {
		validRuntime = validRuntime && ValidOCIImageIDForRegion(expected.ImageOCID, expected.Cell)
	}
	if expected.Role == "netbird-manager" || expected.Runtime == NetBirdProductionRuntime {
		validRuntime = expected.Role == "netbird-manager" && expected.Runtime == NetBirdProductionRuntime &&
			expected.Cell == "GRU" && expected.Architecture == "arm64"
		gates = []string{"netbird-foundation", "netbird-recovery"}
	}
	if !ValidSourceRevision(expected.SourceRevision) || !digestPattern.MatchString(expected.ArtifactSHA256) ||
		!digestPattern.MatchString(expected.QualificationSHA256) || !ValidRegion(expected.Cell) ||
		!ValidEnvironment(expected.Environment) || !validRuntime ||
		expected.Architecture != "amd64" && expected.Architecture != "arm64" || !serviceRolePattern.MatchString(expected.Role) {
		return qualification, fmt.Errorf("%w: candidate scope", ErrProductionQualification)
	}
	envelope, err := trust.DecodeEnvelope(wire)
	if err != nil {
		return qualification, fmt.Errorf("%w: %w", ErrProductionQualification, err)
	}
	policy := trust.Policy{MaxLifetime: MaxUpdateReceiptLifetime}
	var payload []byte
	if len(delegationWire) == 0 {
		payload, err = trust.VerifyCurrent(envelope, ProductionQualificationScope(expected), roots, now, policy)
	} else {
		var delegationEnvelope trust.Envelope
		delegationEnvelope, err = trust.DecodeEnvelope(delegationWire)
		if err == nil {
			var delegation trust.VerifiedDelegation
			delegation, err = trust.VerifyDelegationCurrent(delegationEnvelope, roots, now, policy)
			if err == nil {
				payload, err = trust.VerifyDelegatedCurrent(envelope, ProductionQualificationScope(expected), delegation, now, policy)
			}
		}
	}
	if err != nil {
		return qualification, fmt.Errorf("%w: %w", ErrProductionQualification, err)
	}
	if err := protocol.DecodeStrict(payload, &qualification, trust.MaxPayloadBytes); err != nil {
		return qualification, fmt.Errorf("%w: %w", ErrProductionQualification, err)
	}
	if qualification.Schema != schema || qualification.Candidate != expected || len(qualification.Evidence) != len(gates) {
		return qualification, fmt.Errorf("%w: candidate or required gates", ErrProductionQualification)
	}
	for index, gate := range gates {
		evidence := qualification.Evidence[index]
		if evidence.Gate != gate || !digestPattern.MatchString(evidence.SHA256) ||
			evidence.Bytes <= 0 || evidence.Bytes > MaxProductionEvidenceBytes || evidence.CompletedAt.IsZero() ||
			evidence.CompletedAt.After(envelope.IssuedAt) {
			return qualification, fmt.Errorf("%w: %s evidence", ErrProductionQualification, gate)
		}
	}
	return qualification, nil
}

