func newSwarmHosts(t *testing.T) *swarmHosts {
	t.Helper()
	raftNode := raft.NewNode(raft.NodeOptions{ID: "scaler-manager", Addr: "127.0.0.1:1", StateDir: t.TempDir(),
		TickInterval: 10 * time.Millisecond, TLSCredentials: insecure.NewCredentials(), KeyRotator: &scalerKeys{key: makeKey()}})
	if err := raftNode.JoinAndStart(t.Context()); err != nil {
		t.Fatal(err)
	}
	done := make(chan error, 1)
	go func() { done <- raftNode.Run(t.Context()) }()
	t.Cleanup(func() { raftNode.Cancel(); <-done })
	deadline := time.Now().Add(10 * time.Second)
	for !raftNode.ReadyForProposals() {
		if time.Now().After(deadline) {
			t.Fatal("embedded manager did not elect a leader")
		}
		time.Sleep(10 * time.Millisecond)
	}
	memory := raftNode.MemoryStore()
	listener, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	server := grpc.NewServer()
	api.RegisterControlServer(server, controlapi.NewServer(memory, raftNode, nil, nil, nil))
	go func() { _ = server.Serve(listener) }()
	conn, err := grpc.NewClient(listener.Addr().String(), grpc.WithTransportCredentials(insecure.NewCredentials()))
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = conn.Close(); server.Stop() })
	return &swarmHosts{live: map[string]bool{}, instanceIDs: map[string]string{}, store: memory, control: api.NewControlClient(conn)}
}

func (h *swarmHosts) sync(t *testing.T) {
	t.Helper()
	if err := h.store.Update(func(tx store.Tx) error {
		for name, live := range h.live {
			node := store.GetNode(tx, name)
			create := node == nil
			if create {
				node = &api.Node{ID: name, Role: api.NodeRoleWorker, Spec: api.NodeSpec{DesiredRole: api.NodeRoleWorker, Membership: api.NodeMembershipAccepted,
					Annotations: api.Annotations{Name: name, Labels: map[string]string{"terrascale.instance-id": "ocid-" + name, "terrascale.region": "sa-saopaulo-1"}}}}
				if nodeNumber(name) < FirstPoolNode {
					node.Role = api.NodeRoleManager
					node.Certificate.Role = api.NodeRoleManager
					node.Spec.DesiredRole = api.NodeRoleManager
				}
			}
			if id := h.instanceIDs[name]; id != "" {
				node.Spec.Annotations.Labels["terrascale.instance-id"] = id
			}
			node.Status.State = api.NodeStatus_DOWN
			if live {
				node.Status.State = api.NodeStatus_READY
			}
			if create {
				if err := store.CreateNode(tx, node); err != nil {
					return err
				}
			} else if err := store.UpdateNode(tx, node); err != nil {
				return err
			}
		}
		for i, desired := range h.desired {
			id := fmt.Sprintf("task-%d", i)
			serviceID := "service-" + desired.Role
			if store.GetService(tx, serviceID) == nil {
				if err := store.CreateService(tx, &api.Service{ID: serviceID, Spec: api.ServiceSpec{Annotations: api.Annotations{Name: serviceID, Labels: map[string]string{"terrascale.role": desired.Role}}}}); err != nil {
					return err
				}
			}
			task := store.GetTask(tx, id)
			create := task == nil
			if create {
				task = &api.Task{ID: id, NodeID: desired.Node, ServiceID: serviceID, DesiredState: api.TaskStateRunning, Status: api.TaskStatus{State: api.TaskStateRunning}}
			}
			if desired.Withdrawn {
				task.DesiredState = api.TaskStateShutdown
				task.Status.State = api.TaskStateShutdown
			}
			if create {
				if err := store.CreateTask(tx, task); err != nil {
					return err
				}
			} else if err := store.UpdateTask(tx, task); err != nil {
				return err
			}
		}
		return nil
	}); err != nil {
		t.Fatal(err)
	}
}

func nodesByInstance(nodes []*api.Node) map[string]*api.Node {
	byInstance := make(map[string]*api.Node, len(nodes))
	for _, node := range nodes {
		id := node.Spec.Annotations.Labels["terrascale.instance-id"]
		if id == "" {
			continue
		}
		if _, exists := byInstance[id]; exists {
			byInstance[id] = nil
			continue
		}
		byInstance[id] = node
	}
	return byInstance
}

func (s *Scaler) admitted(node *api.Node, role api.NodeRole) bool {
	region, ok := catalog.LookupName(s.Cell)
	return ok && node != nil && node.Spec.Annotations.Name != "" &&
		node.Spec.Annotations.Labels["terrascale.region"] == region.OCIRegion &&
		node.Role == role && node.Certificate.Role == role && node.Spec.DesiredRole == role && node.Spec.Membership == api.NodeMembershipAccepted
}

func (s *Scaler) cordon(ctx context.Context, t *tick) error {
	action := t.record.Action
	if err := s.Leader.Guard(ctx, t.epoch); err != nil {
		return err
	}
	safe, err := s.retireSafe(ctx, action.Node, action.InstanceID)
	if err != nil {
		t.pool.Pending = err.Error()
		return nil
	}
	if !safe {
		t.pool.Pending = "node retirement safety is unavailable or the node holds protected tasks"
		return nil
	}
	if err := s.setAvailability(ctx, action.Node, action.InstanceID, api.NodeAvailabilityDrain, t.epoch); err != nil {
		return fmt.Errorf("cordon %s: %w", action.Node, err)
	}
	action.Step = stepDrain
	return nil
}

func (s *Scaler) protectedNodes(ctx context.Context) (map[string]bool, error) {
	services, err := s.Control.ListServices(ctx, &api.ListServicesRequest{})
	if err != nil {
		return nil, fmt.Errorf("list services for retirement safety: %w", err)
	}
	known := map[string]*api.Service{}
	for _, service := range services.Services {
		known[service.ID] = service
	}
	tasks, err := s.Control.ListTasks(ctx, &api.ListTasksRequest{})
	if err != nil {
		return nil, fmt.Errorf("list tasks for retirement safety: %w", err)
	}
	protected := map[string]bool{}
	for _, task := range tasks.Tasks {
		service := known[task.ServiceID]
		if service == nil || service.Spec.Annotations.Labels["terrascale.role"] == "" ||
			stateful(service.Spec.Annotations.Labels) || stateful(task.Annotations.Labels) {
			protected[task.NodeID] = true
		}
	}
	return protected, nil
}

func (s *Scaler) worker(ctx context.Context, name, instanceID string) (*api.Node, error) {
	if name == "" || instanceID == "" {
		return nil, errors.New("worker retirement requires an exact node and OCI instance identity")
	}
	nodes, err := s.Control.ListNodes(ctx, &api.ListNodesRequest{})
	if err != nil {
		return nil, fmt.Errorf("find worker %s: %w", name, err)
	}
	node := nodesByInstance(nodes.Nodes)[instanceID]
	if !s.admitted(node, api.NodeRoleWorker) {
		return nil, fmt.Errorf("worker %s has no unique admitted OCI instance %s", name, instanceID)
	}
	return node, nil
}

func (s *Scaler) setAvailability(ctx context.Context, name, instanceID string, availability api.NodeSpec_Availability, epoch uint64) error {
	node, err := s.worker(ctx, name, instanceID)
	if err != nil {
		return err
	}
	if node.Spec.Annotations.Labels["terrascale.instance-id"] != instanceID {
		return fmt.Errorf("node %s is not instance %s", name, instanceID)
	}
	if node.Spec.Availability == availability {
		return nil
	}
	spec := node.Spec.Copy()
	spec.Availability = availability
	if err := s.Leader.Guard(ctx, epoch); err != nil {
		return err
	}
	_, err = s.Control.UpdateNode(ctx, &api.UpdateNodeRequest{NodeID: node.ID, NodeVersion: &node.Meta.Version, Spec: spec})
	return err
}

func (s *Scaler) retireSafe(ctx context.Context, name, instanceID string) (bool, error) {
	node, err := s.worker(ctx, name, instanceID)
	if err != nil {
		return false, err
	}
	protected, err := s.protectedNodes(ctx)
	if err != nil {
		return false, err
	}
	if node.Spec.Annotations.Labels["terrascale.instance-id"] != instanceID || protected[node.ID] || s.CanRetire == nil {
		return false, nil
	}
	if err := s.CanRetire(ctx, name, instanceID); err != nil {
		return false, fmt.Errorf("retirement safety for %s: %w", name, err)
	}
	return true, nil
}

func (s *Server) GetNode(_ context.Context, request *api.GetNodeRequest) (*api.GetNodeResponse, error) {
	if request.NodeID == "" {
		return nil, status.Error(codes.InvalidArgument, errInvalidArgument.Error())
	}

	var node *api.Node
	s.store.View(func(tx store.ReadTx) {
		node = store.GetNode(tx, request.NodeID)
	})
	if node == nil {
		return nil, status.Errorf(codes.NotFound, "node %s not found", request.NodeID)
	}

	if s.raft != nil {
		memberlist := s.raft.GetMemberlist()
		for _, member := range memberlist {
			if member.NodeID == node.ID {
				node.ManagerStatus = &api.ManagerStatus{
					RaftID:       member.RaftID,
					Addr:         member.Addr,
					Leader:       member.Status.Leader,
					Reachability: member.Status.Reachability,
				}
				break
			}
		}
	}

	return &api.GetNodeResponse{
		Node: node,
	}, nil
}

func (s *Server) ListNodes(_ context.Context, request *api.ListNodesRequest) (*api.ListNodesResponse, error) {
	var (
		nodes []*api.Node
		err   error
	)
	s.store.View(func(tx store.ReadTx) {
		switch {
		case request.Filters != nil && len(request.Filters.Names) > 0:
			nodes, err = store.FindNodes(tx, buildFilters(store.ByName, request.Filters.Names))
		case request.Filters != nil && len(request.Filters.NamePrefixes) > 0:
			nodes, err = store.FindNodes(tx, buildFilters(store.ByNamePrefix, request.Filters.NamePrefixes))
		case request.Filters != nil && len(request.Filters.IDPrefixes) > 0:
			nodes, err = store.FindNodes(tx, buildFilters(store.ByIDPrefix, request.Filters.IDPrefixes))
		case request.Filters != nil && len(request.Filters.Roles) > 0:
			filters := make([]store.By, 0, len(request.Filters.Roles))
			for _, v := range request.Filters.Roles {
				filters = append(filters, store.ByRole(v))
			}
			nodes, err = store.FindNodes(tx, store.Or(filters...))
		case request.Filters != nil && len(request.Filters.Memberships) > 0:
			filters := make([]store.By, 0, len(request.Filters.Memberships))
			for _, v := range request.Filters.Memberships {
				filters = append(filters, store.ByMembership(v))
			}
			nodes, err = store.FindNodes(tx, store.Or(filters...))
		default:
			nodes, err = store.FindNodes(tx, store.All)
		}
	})
	if err != nil {
		return nil, err
	}

	if request.Filters != nil {
		nodes = filterNodes(nodes,
			func(e *api.Node) bool {
				if len(request.Filters.Names) == 0 {
					return true
				}
				if e.Description == nil {
					return false
				}
				return filterContains(e.Description.Hostname, request.Filters.Names)
			},
			func(e *api.Node) bool {
				if len(request.Filters.NamePrefixes) == 0 {
					return true
				}
				if e.Description == nil {
					return false
				}
				return filterContainsPrefix(e.Description.Hostname, request.Filters.NamePrefixes)
			},
			func(e *api.Node) bool {
				return filterContainsPrefix(e.ID, request.Filters.IDPrefixes)
			},
			func(e *api.Node) bool {
				if len(request.Filters.Labels) == 0 {
					return true
				}
				if e.Description == nil {
					return false
				}
				return filterMatchLabels(e.Description.Engine.Labels, request.Filters.Labels)
			},
			func(e *api.Node) bool {
				if len(request.Filters.NodeLabels) == 0 {
					return true
				}
				return filterMatchLabels(e.Spec.Annotations.Labels, request.Filters.NodeLabels)
			},
			func(e *api.Node) bool {
				if len(request.Filters.Roles) == 0 {
					return true
				}
				for _, c := range request.Filters.Roles {
					if c == e.Role {
						return true
					}
				}
				return false
			},
			func(e *api.Node) bool {
				if len(request.Filters.Memberships) == 0 {
					return true
				}
				for _, c := range request.Filters.Memberships {
					if c == e.Spec.Membership {
						return true
					}
				}
				return false
			},
		)
	}

	// Add in manager information on nodes that are managers
	if s.raft != nil {
		memberlist := s.raft.GetMemberlist()

		for _, node := range nodes {
			for _, member := range memberlist {
				if member.NodeID == node.ID {
					node.ManagerStatus = &api.ManagerStatus{
						RaftID:       member.RaftID,
						Addr:         member.Addr,
						Leader:       member.Status.Leader,
						Reachability: member.Status.Reachability,
					}
					break
				}
			}
		}
	}

	return &api.ListNodesResponse{
		Nodes: nodes,
	}, nil
}

func (s *Server) UpdateNode(_ context.Context, request *api.UpdateNodeRequest) (*api.UpdateNodeResponse, error) {
	if request.NodeID == "" || request.NodeVersion == nil {
		return nil, status.Error(codes.InvalidArgument, errInvalidArgument.Error())
	}
	if err := validateNodeSpec(request.Spec); err != nil {
		return nil, err
	}

	var (
		node   *api.Node
		member *membership.Member
	)

	err := s.store.Update(func(tx store.Tx) error {
		node = store.GetNode(tx, request.NodeID)
		if node == nil {
			return status.Errorf(codes.NotFound, "node %s not found", request.NodeID)
		}

		// Demotion sanity checks.
		if node.Spec.DesiredRole == api.NodeRoleManager && request.Spec.DesiredRole == api.NodeRoleWorker {
			// Check for manager entries in Store.
			managers, err := store.FindNodes(tx, store.ByRole(api.NodeRoleManager))
			if err != nil {
				return status.Errorf(codes.Internal, "internal store error: %v", err)
			}
			if len(managers) == 1 && managers[0].ID == node.ID {
				return status.Errorf(codes.FailedPrecondition, "attempting to demote the last manager of the swarm")
			}

			// Check for node in memberlist
			if member = s.raft.GetMemberByNodeID(request.NodeID); member == nil {
				return status.Errorf(codes.NotFound, "can't find manager in raft memberlist")
			}

			// Quorum safeguard
			if !s.raft.CanRemoveMember(member.RaftID) {
				return status.Errorf(codes.FailedPrecondition, "can't remove member from the raft: this would result in a loss of quorum")
			}
		}

		node.Meta.Version = *request.NodeVersion
		node.Spec = *request.Spec.Copy()
		return store.UpdateNode(tx, node)
	})
	if err != nil {
		return nil, err
	}

	return &api.UpdateNodeResponse{
		Node: node,
	}, nil
}

func UpdateNode(tx Tx, n *api.Node) error {
	return tx.update(tableNode, n)
}

func GetNode(tx ReadTx, id string) *api.Node {
	n := tx.get(tableNode, id)
	if n == nil {
		return nil
	}
	return n.(*api.Node)
}
